import{_ as s,C as t,c as n,o as r,aj as l,G as i,w as u}from"./chunks/framework.Bfdr4H5E.js";const v=JSON.parse('{"title":"Personal Survival","description":"","frontmatter":{"outline":"deep","prev":{"text":"Goals & Targets","link":"/trading-with-pav/goals-targets"},"next":{"text":"Mastery of Trading Psychology","link":"/trading-with-pav/mastery-of-trading-psychology"}},"headers":[],"relativePath":"trading-with-pav/personal-survival.md","filePath":"trading-with-pav/personal-survival.md"}'),h={name:"trading-with-pav/personal-survival.md"};function c(d,e,p,m,g,y){const o=t("GraphComment"),a=t("ClientOnly");return r(),n("div",null,[e[0]||(e[0]=l('<h1 id="personal-survival" tabindex="-1">Personal Survival <a class="header-anchor" href="#personal-survival" aria-label="Permalink to &quot;Personal Survival&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#prerequisites-for-survival">Prerequisites for Survival</a><ul><li><a href="#realistic-expectations">Realistic Expectations</a></li><li><a href="#motivation-to-take-positive-action">Motivation to take Positive Action</a></li><li><a href="#passion-for-the-process">Passion for the Process</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><ul><li>We established earlier that the success of our trading business requires both <ol><li>Financial Survival &amp;</li><li>Personal Survival</li></ol></li><li>This chapter examines personal survival – both throughout the learning process and then our ongoing Trading Career.</li><li>Survival is a result of certain prerequisites being in place (without them you are going to struggle to even get started) and then maintenance of a peak performance mindset.</li><li>We will be touching briefly on the topic of trading psychology.</li><li>A complete investigation of this topic is beyond the scope of this Course (perhaps a future book or video on YouTube).</li><li>In particular, we will not cover the background theory – the cause and nature of the various psychological influences on your decision making and actions.</li><li>While this theory is important, <strong>I prefer to focus on the practical</strong>; sharing the tools and techniques which we use to manage our trading mindset.</li></ul><h2 id="prerequisites-for-survival" tabindex="-1">Prerequisites for Survival <a class="header-anchor" href="#prerequisites-for-survival" aria-label="Permalink to &quot;Prerequisites for Survival&quot;">​</a></h2><ul><li>Before we get to the tools and techniques for maintenance of a peak performance mindset, there are some prerequisites that must be in place: <ol><li>Realistic Expectations</li><li>Motivation to take Positive Action</li><li>Passion for the Process</li></ol></li><li>Let’s look briefly at all three.</li></ul><h3 id="realistic-expectations" tabindex="-1">Realistic Expectations <a class="header-anchor" href="#realistic-expectations" aria-label="Permalink to &quot;Realistic Expectations&quot;">​</a></h3><ul><li>You must accept that this is a journey. There is NO Holy Grail solution.</li><li>It’s a journey of personal growth and development. And it WILL take time.</li><li>It will be easier once we have a graduated plan for our development.</li><li>We will put one together in (<a href="https://ystc.in/trading-with-pav/the-development-stages/" target="_blank" rel="noreferrer">Volume 7</a>).</li><li>However the rate at which you will personally develop towards consistent profitability is unknown.</li><li>If you already have experience, this course may provide the missing key that has you there in quick time.</li><li>It may take you only a matter of months. But for the majority, it will likely take a number of years.</li><li>Accepting that it’s a journey of unknown duration, you need to have realistic expectations.</li><li>You need to display patience.</li><li><strong>Your lifestyle needs to be structured such that success is not required within any deadline, and sufficient income is available for your financial survival throughout the learning process.</strong></li><li>Without this, the stress will be too great. And you will most likely not make it.</li></ul><h3 id="motivation-to-take-positive-action" tabindex="-1">Motivation to take Positive Action <a class="header-anchor" href="#motivation-to-take-positive-action" aria-label="Permalink to &quot;Motivation to take Positive Action&quot;">​</a></h3><ul><li>Use a motivation journal for daily motivational reinforcement.</li><li>Available to download on our website below this article.</li><li>In terms of prerequisites though You absolutely must be 100% clear as to why you want to become a consistently profitable trader.</li><li>Your reason why, or your purpose, must be strong enough to get you up each day, excited, ready and willing to face the upcoming challenges.</li></ul><blockquote><p>“The only way we’re going to make a change now is if we create a sense of urgency that’s so intense that we’re compelled to follow through“.</p><p>by Anthony Robbins</p></blockquote><ul><li>Without a strong and clear reason why, I promise you will not make it in this game.</li><li>I recommend documenting your reason why in one of 2 ways.</li><li>Try both, to see which works for you best.</li><li>(Available to download on our website below this article)</li></ul><p>The <strong>first option</strong> is to use the emotions of <strong>pain and pleasure</strong>.</p><p>You need to clearly identify the pain that comes from failure to achieve trading success. And you need to be crystal clear about the pleasure that you will derive from trading success.</p><p>Your reasons will change over time; that’s fine. For now, ask yourself the following questions:</p><ul><li><p>“What will it mean for my life and my happiness if I fail to put in the necessary work to become a consistently profitable and successful trader?”</p><ul><li>Take some time to think of your response, and write it down.</li><li>Then look deeper. Ask, “What does that mean?”, and again write down your answer.</li><li>Keep asking, “What does that mean?” until you get down to the very core feelings associated with the pain of failure.</li></ul></li><li><p>“What will it mean for my life and my happiness when I succeed, and can call myself a consistently profitable trader?”</p><ul><li>Take some time to think of your response, and write it down.</li><li>Then look deeper. Ask, “What does that mean?”, and again write down your answer.</li><li>Keep asking, “What does that mean?” until you get down to the very core feelings associated with the pleasure of success.</li></ul></li></ul><p>If you haven’t done this exercise, take a break from reading now, get a piece of paper, and examine your pain and pleasure motivators.</p><p>The <strong>second option</strong> (and the one I prefer) based upon an article titled “<strong>The Four Emotions That<br> Can Lead to Life Change</strong>”, by Jim Rohn. Do a Google Search and you’ll find it, if interested.</p><ul><li>Jim Rohn says there are four basic emotions which cause people to take decisive action – <ol><li>disgust,</li><li>decision,</li><li>desire and</li><li>resolve.</li></ol></li></ul><p>Add to your previous reasons why, a sequence of new statements based upon each of these four emotions. You may get the same response as previously, when using pain and pleasure. That’s fine. Sometimes though, you’ll find some new insight through approaching the subject from this different direction.</p><p><strong>Disgust</strong></p><p>There is, in my opinion, no greater motivator than disgust. Absolute disgust at my job will keep me working towards trading success. Absolute disgust at my previous undisciplined attempts to trade will have me moving forward in a more disciplined and businesslike manner.</p><p>What is it that you’re disgusted with? What is it that you wish to never experience again? What is it that has you saying, “No More! Never Again! Enough is Enough! It’s Time to Change!”?</p><p><strong>Decision</strong></p><p>Life will provide you with many competing priorities. Your time is limited. There is only so much you can do each day.</p><p>Make a clear decision – trading is a priority. You will do this. You will do this properly.<br> Document that decision. Put it in writing. And tell everyone close to you.</p><p><strong>Desire</strong></p><p>Write down a desire statement. What do you want to achieve from trading. There may be some overlap here with the previous pleasure statements. Be sure though that the desire statement is one based upon a feeling.</p><p>For example, it’s not the money that you desire. It’s the feeling that this money will give you.<br> Document your desire. What do you want to achieve from trading? Put it in writing.</p><p><strong>Resolve</strong></p><p>Resolve to do whatever is necessary to achieve your goals. You’ve got the disgust to move away from. You’ve decided to take action. You have the desire to move towards. It’s time to resolve to do whatever it takes to make it.</p><p>Document your resolve statement.</p><p>Resolve to never quit, no matter what comes ahead.</p><p>Here’s a great quote</p><blockquote><p>“Not dead. Can’t Quit.”</p><p>by Richard Machowicz</p></blockquote><h3 id="passion-for-the-process" tabindex="-1">Passion for the Process <a class="header-anchor" href="#passion-for-the-process" aria-label="Permalink to &quot;Passion for the Process&quot;">​</a></h3><ul><li>Armed with realistic expectations and motivation to take positive action, the final prerequisite is a Passion for the process of trading. <ul><li>If you don’t enjoy the daily routines, you will NOT survive.</li><li>You may hate your previous life, and greatly desire the rewards that come from trading success.</li><li>You might be motivated for action. But if you don’t absolutely LOVE the process of trading, I guarantee you will FAIL.</li><li>The motivation, disgust and desire will not be enough. //(From Previous PDF)</li></ul></li><li>So, take some time to consider <ul><li>Whether or not you really love this game?</li><li>Do you love the analysis?</li><li>Do you love the challenge?</li><li>Are you OK with making mistakes, reviewing your decisions and trading actions, and trying to find the way forward?</li><li>Are you willing to make mistakes? Forgiving yourself again and again and again?</li><li>If not… perhaps trading is not the right path for you?</li><li>It’s OK. It’s best to admit that early, before damaging your financial and psychological capital.</li></ul></li><li>You have seen the strategy. You have a good idea of the degree of work required to conduct analysis and trade the markets.</li><li>Are you excited by the challenge ahead? Take some time out to confirm your passion for this game.</li></ul><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',37)),i(a,null,{default:u(()=>[i(o)]),_:1})])}const w=s(h,[["render",c]]);export{v as __pageData,w as default};
